import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { isValidSessionHost, sessionHostKind } from '~/server/services/blocks/dev-tunnel-session';
import {
  base32Decode,
  base32Encode,
  decodePreviewLabel,
  mintPreviewLabel,
  parsePreviewSigningKey,
  parsePreviewSigningKeyResult,
} from '~/server/services/blocks/preview-session-host';

/**
 * The App Assistant direct-preview session host against the SHARED test vector
 * (`fixtures/preview-label-v1.json`): a byte-identical copy of the preview gateway's own vector,
 * generated by an implementation independent of both (Python stdlib). This is a wire-contract
 * pin: the gateway verifies the label civitai mints, so the bytes must agree exactly.
 */

interface Vector {
  now: number;
  keys: Record<'current' | 'previous', { kid: number; keyHex: string }>;
  valid: Array<{
    name: string;
    label: string;
    kid: number;
    previewId: string;
    userId: number;
    exp: number;
    labelBytesHex: string;
    macHex: string;
  }>;
  invalid: Array<{ name: string; label: string; reason: string }>;
}

const VECTOR = JSON.parse(
  fs.readFileSync(path.join(__dirname, 'fixtures/preview-label-v1.json'), 'utf8')
) as Vector;
const keyFor = (kid: number) =>
  Buffer.from(
    kid === VECTOR.keys.current.kid ? VECTOR.keys.current.keyHex : VECTOR.keys.previous.keyHex,
    'hex'
  );
const DOMAINS = { appsDomain: 'apps.example', previewDomain: 'preview.example' };

describe('the session-host label, against the shared test vector', () => {
  it('the vector is the size and shape the gateway pins (a truncated copy fails here)', () => {
    expect(VECTOR.valid).toHaveLength(2);
    expect(VECTOR.invalid).toHaveLength(8);
    expect(VECTOR.invalid.map((v) => v.reason).sort()).toEqual([
      'bad_mac',
      'bad_mac',
      'bad_version',
      'expired',
      'malformed',
      'non_canonical',
      'non_canonical',
      'unknown_kid',
    ]);
  });

  it('minting each valid case reproduces its label byte for byte, and decodes back to its fields', () => {
    for (const v of VECTOR.valid) {
      const fields = { kid: v.kid, previewId: v.previewId, userId: v.userId, exp: v.exp };
      expect(mintPreviewLabel(fields, keyFor(v.kid)), v.name).toBe(v.label);
      expect(base32Decode(v.label.slice(1))?.toString('hex'), v.name).toBe(v.labelBytesHex);
      expect(decodePreviewLabel(v.label), v.name).toEqual({ ok: true, ...fields });
    }
  });

  it('pins one label as a literal, so a vector edited in step with a broken minter still fails', () => {
    expect(
      mintPreviewLabel(
        {
          kid: 2,
          previewId: '9f86d081884c7d659a2feaa0c55ad015',
          userId: 4328719365,
          exp: 1795075200,
        },
        Buffer.from('202122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f', 'hex')
      )
    ).toBe('sckpynuebrbgh2zm2f7vkbrk22akqcaqdaqcwv7vmqcbzawxned4cvl4enkzes');
  });

  it('refuses the spare-bit, upper-case, wrong-length and version-2 labels with their own reason', () => {
    for (const v of VECTOR.invalid.filter((x) =>
      ['non_canonical', 'malformed', 'bad_version'].includes(x.reason)
    )) {
      expect(decodePreviewLabel(v.label), v.name).toEqual({ ok: false, reason: v.reason });
    }
  });

  it('the spare bit is invisible to the decoder: only the re-encode comparison refuses it', () => {
    const spare = VECTOR.invalid.find((v) => v.name.startsWith('spare'))!.label;
    expect(spare).not.toBe(VECTOR.valid[0].label);
    expect(base32Decode(spare.slice(1))).toEqual(base32Decode(VECTOR.valid[0].label.slice(1)));
  });

  it('a tampered label or one MACd under the other key is not what civitai would mint for its fields', () => {
    // The MAC, key-id and expiry refusals are the gateway's to make (civitai never verifies a
    // MAC: its records are its own). What civitai can be held to is that its minter, given the
    // decoded fields, never produces a bad_mac label.
    for (const v of VECTOR.invalid.filter((x) => x.reason === 'bad_mac')) {
      const d = decodePreviewLabel(v.label);
      expect(d.ok, v.name).toBe(true);
      if (!d.ok) continue;
      const { kid, previewId, userId, exp } = d;
      expect(mintPreviewLabel({ kid, previewId, userId, exp }, keyFor(kid)), v.name).not.toBe(
        v.label
      );
    }
  });

  it('base32 is RFC 4648 lowercase, unpadded, and round-trips', () => {
    expect(base32Encode(Buffer.from('foobar'))).toBe('mzxw6ytboi');
    for (let n = 0; n < 40; n++) {
      const b = Buffer.from(Array.from({ length: n }, (_, i) => (i * 37 + n) & 0xff));
      expect(base32Decode(base32Encode(b))).toEqual(b);
    }
  });
});

describe('the signing key from its env form', () => {
  const k32 = Buffer.alloc(32, 7).toString('base64');
  it('reads {kid, key}; anything else leaves direct preview off', () => {
    expect(parsePreviewSigningKey(JSON.stringify({ kid: 3, key: k32 }))).toEqual({
      kid: 3,
      key: Buffer.alloc(32, 7),
    });
    for (const bad of [
      undefined,
      '',
      '  ',
      'not json',
      JSON.stringify({ kid: 16, key: k32 }),
      JSON.stringify({ kid: 1.5, key: k32 }),
      JSON.stringify({ kid: 3, key: Buffer.alloc(31).toString('base64') }),
      JSON.stringify({ kid: 3, key: '!!!' }),
    ])
      expect(parsePreviewSigningKey(bad), String(bad)).toBeNull();
  });

  // The preview gateway's key-set value (its `parsePreviewKeys`), so one value is set on both sides.
  const k32b = Buffer.alloc(32, 8).toString('base64');
  it('reads the gateway key set {current, previous?}, minting with current', () => {
    expect(
      parsePreviewSigningKey(
        JSON.stringify({ current: { kid: 2, key: k32b }, previous: { kid: 3, key: k32 } })
      )
    ).toEqual({ kid: 2, key: Buffer.alloc(32, 8) });
    expect(parsePreviewSigningKey(JSON.stringify({ current: { kid: 5, key: k32b } }))).toEqual({
      kid: 5,
      key: Buffer.alloc(32, 8),
    });
  });

  it('refuses a key set the gateway would refuse, naming the field and never the key', () => {
    const cases: Array<[unknown, string]> = [
      [
        { current: { kid: 2, key: k32b }, previous: { kid: 2, key: k32 } },
        'previous.kid must differ from current.kid',
      ],
      [
        { current: { kid: 2, key: k32b }, previous: { kid: 3, key: '!!!' } },
        'previous.key must be base64',
      ],
      [{ current: { kid: 16, key: k32b } }, 'current.kid must be an integer 0..15'],
      [{ current: null }, 'current.kid must be an integer 0..15'],
      [
        { current: { kid: 2, key: Buffer.alloc(31).toString('base64') } },
        'current.key must be at least 32 bytes',
      ],
    ];
    for (const [value, error] of cases) {
      const parsed = parsePreviewSigningKeyResult(JSON.stringify(value));
      expect(parsed, error).toEqual({ ok: false, reason: 'invalid', error });
    }
    expect(parsePreviewSigningKeyResult('{nope')).toEqual({
      ok: false,
      reason: 'invalid',
      error: 'not JSON',
    });
    expect(parsePreviewSigningKeyResult(undefined)).toEqual({ ok: false, reason: 'unset' });
  });
});

describe('the one host predicate for a session record', () => {
  const label = VECTOR.valid[0].label;
  const direct = `${label}.${DOMAINS.previewDomain}`;
  const tunnel = `dev-0123456789abcdef.${DOMAINS.appsDomain}`;

  it('a tunnel record needs a dev host, a direct record a session host under the preview domain', () => {
    expect(isValidSessionHost({ host: tunnel }, DOMAINS)).toBe(true);
    expect(isValidSessionHost({ host: direct, transport: 'direct' }, DOMAINS)).toBe(true);
    // Crossed: each shape is refused under the other transport.
    expect(isValidSessionHost({ host: direct }, DOMAINS)).toBe(false);
    expect(isValidSessionHost({ host: tunnel, transport: 'direct' }, DOMAINS)).toBe(false);
  });

  it('refuses a direct host when the preview domain is unset, under another domain, or non-canonical', () => {
    expect(
      isValidSessionHost({ host: direct, transport: 'direct' }, { appsDomain: 'apps.example' })
    ).toBe(false);
    expect(
      isValidSessionHost({ host: `${label}.elsewhere.example`, transport: 'direct' }, DOMAINS)
    ).toBe(false);
    const spare = VECTOR.invalid.find((v) => v.name.startsWith('spare'))!.label;
    expect(sessionHostKind(`${spare}.${DOMAINS.previewDomain}`, DOMAINS)).toBeNull();
    expect(sessionHostKind(`x.${direct}`, DOMAINS)).toBeNull();
  });
});
